def most_common_pair(pairs):
    counts = {}
    for p in pairs:
        counts[p] = counts.get(p, 0) + 1
    best_pair = None
    best_count = -1
    for p in sorted(counts):
        c = counts[p]
        if c > best_count:
            best_count = c
            best_pair = p
    return best_pair

