def is_valid_css_rgb_string(s):
    import re
    match = re.fullmatch(r'rgb\((\d{1,3}), (\d{1,3}), (\d{1,3})\)', s)
    if not match:
        return False
    for grp in match.groups():
        if grp != '0' and grp[0] == '0':
            return False
        if int(grp) > 255:
            return False
    return True

