    return f'{base}-{suffix}'

def merge_two_sorted_lists_dedup(a, b):
    i, j = 0, 0
    out = []
    while i < len(a) and j < len(b):
        if a[i] < b[j]:
            val = a[i]; i += 1
        elif b[j] < a[i]:
            val = b[j]; j += 1
        else:
            val = a[i]; i += 1; j += 1
        if not out or out[-1] != val:
            out.append(val)
    rest = a[i:] + b[j:]
